using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Net.WebSockets;using System.Security.Cryptography;using System.Text;using System.Threading;
namespace Iris {
    // One authenticated connection per explicit action. No idle network polling or server-side state guesses.
    public interface IObsTransport : IDisposable {void Send(object message,CancellationToken token);Dictionary<string,object> Receive(CancellationToken token);}
    public sealed class ObsSocket : IObsTransport {
        readonly ClientWebSocket socket=new ClientWebSocket();
        public ObsSocket(string endpoint,CancellationToken token){socket.Options.AddSubProtocol("obswebsocket.json");try{socket.ConnectAsync(new Uri(endpoint),token).GetAwaiter().GetResult();}catch{socket.Dispose();throw new InvalidOperationException(L.T("OBS nicht erreichbar. OBS öffnen und unter Werkzeuge → WebSocket-Servereinstellungen aktivieren."));}}
        public void Send(object value,CancellationToken token){var bytes=Encoding.UTF8.GetBytes(IntegrationJson.Stringify(value));socket.SendAsync(new ArraySegment<byte>(bytes),WebSocketMessageType.Text,true,token).GetAwaiter().GetResult();}
        public Dictionary<string,object> Receive(CancellationToken token){using(var data=new MemoryStream()){var bytes=new byte[8192];WebSocketReceiveResult r;do{r=socket.ReceiveAsync(new ArraySegment<byte>(bytes),token).GetAwaiter().GetResult();if(r.MessageType!=WebSocketMessageType.Text)throw new InvalidDataException(L.T("OBS hat die Verbindung geschlossen oder ein ungültiges Paket gesendet."));data.Write(bytes,0,r.Count);if(data.Length>1024*1024)throw new InvalidDataException(L.T("OBS-Antwort zu groß."));}while(!r.EndOfMessage);return IntegrationJson.Parse(Encoding.UTF8.GetString(data.ToArray()));}}
        public void Dispose(){socket.Dispose();}
    }
    public sealed class ObsConnection {
        readonly IObsTransport transport;public ObsConnection(IObsTransport transport,string password,CancellationToken token){this.transport=transport;var hello=transport.Receive(token);if(IntegrationJson.Number(hello,"op")!=0)throw new InvalidDataException(L.T("OBS-WebSocket 5 erwartet."));var data=IntegrationJson.Get(hello,"d");var identify=new Dictionary<string,object>{{"rpcVersion",1},{"eventSubscriptions",0}};var auth=IntegrationJson.Get(data,"authentication");if(auth!=null){if(string.IsNullOrEmpty(password))throw new InvalidOperationException(L.T("OBS verlangt ein Passwort. Unter Verbindungen hinterlegen."));identify["authentication"]=Authentication(password,IntegrationJson.Text(auth,"salt"),IntegrationJson.Text(auth,"challenge"));}transport.Send(new{op=1,d=identify},token);if(IntegrationJson.Number(transport.Receive(token),"op")!=2)throw new InvalidOperationException(L.T("OBS-Anmeldung abgelehnt. Passwort und WebSocket-Version prüfen."));}
        public static string Authentication(string password,string salt,string challenge){using(var sha=SHA256.Create()){string secret=Convert.ToBase64String(sha.ComputeHash(Encoding.UTF8.GetBytes(password+salt)));return Convert.ToBase64String(sha.ComputeHash(Encoding.UTF8.GetBytes(secret+challenge)));}}
        public Dictionary<string,object> Request(string name,object data,CancellationToken token){string id=Guid.NewGuid().ToString("N");transport.Send(new{op=6,d=new{requestType=name,requestId=id,requestData=data??new object()}},token);for(int i=0;i<32;i++){var message=transport.Receive(token);if(IntegrationJson.Number(message,"op")!=7)continue;var body=IntegrationJson.Get(message,"d");if(IntegrationJson.Text(body,"requestId")!=id)continue;var status=IntegrationJson.Get(body,"requestStatus");if(!IntegrationJson.Bool(status,"result"))throw new InvalidOperationException("OBS: "+IntegrationJson.Text(status,"comment")+" ("+IntegrationJson.Text(status,"code")+")");return IntegrationJson.Get(body,"responseData") as Dictionary<string,object>??new Dictionary<string,object>();}throw new InvalidDataException(L.T("Keine zugehörige OBS-Antwort."));}
        public AddonResult Execute(AddonAction action,CancellationToken token){string op=action.Kind.Substring(4);if(op=="status"){var record=Request("GetRecordStatus",null,token);var stream=Request("GetStreamStatus",null,token);return AddonResult.State(L.T("Aufnahme: ")+(IntegrationJson.Bool(record,"outputActive")?L.T("läuft · ")+IntegrationJson.Text(record,"outputTimecode"):L.T("aus"))+"\nStream: "+(IntegrationJson.Bool(stream,"outputActive")?L.T("läuft · ")+IntegrationJson.Text(stream,"outputTimecode"):L.T("aus")),L.T("OBS-Status gelesen"));}
            if(op=="scenes"||op=="inputs"){var value=Request(op=="scenes"?"GetSceneList":"GetInputList",null,token);var names=IntegrationJson.Array(value,op=="scenes"?"scenes":"inputs").Select(x=>IntegrationJson.Text(x,op=="scenes"?"sceneName":"inputName")).ToArray();return AddonResult.Of(AddonResultCode.Succeeded,names.Length==0?L.T("Keine Einträge."):string.Join("\n",names));}
            if(op=="scene"){Request("SetCurrentProgramScene",new{sceneName=action.Target},token);var state=Request("GetCurrentProgramScene",null,token);return AddonResult.State(L.T("Programmszene: ")+IntegrationJson.Text(state,"currentProgramSceneName"),L.T("Szene gelesen"));}
            if(op=="input-mute"){var before=Request("GetInputMute",new{inputName=action.Target},token);Request("SetInputMute",new{inputName=action.Target,inputMuted=!IntegrationJson.Bool(before,"inputMuted")},token);bool muted=IntegrationJson.Bool(Request("GetInputMute",new{inputName=action.Target},token),"inputMuted");return AddonResult.State(action.Target+(muted?L.T(" stumm"):L.T(" an")),muted?"muted":"unmuted");}
            if(op=="source"){var pair=action.Target.Split('|').Select(s=>s.Trim()).ToArray();int id=(int)IntegrationJson.Number(Request("GetSceneItemId",new{sceneName=pair[0],sourceName=pair[1]},token),"sceneItemId");bool before=IntegrationJson.Bool(Request("GetSceneItemEnabled",new{sceneName=pair[0],sceneItemId=id},token),"sceneItemEnabled");Request("SetSceneItemEnabled",new{sceneName=pair[0],sceneItemId=id,sceneItemEnabled=!before},token);bool after=IntegrationJson.Bool(Request("GetSceneItemEnabled",new{sceneName=pair[0],sceneItemId=id},token),"sceneItemEnabled");return AddonResult.State(pair[1]+(after?" sichtbar":" ausgeblendet"),after?"sichtbar":"ausgeblendet");}
            string request=op=="record-start"?"StartRecord":op=="record-stop"?"StopRecord":op=="stream-start"?"StartStream":op=="stream-stop"?"StopStream":op=="replay-start"?"StartReplayBuffer":op=="replay-stop"?"StopReplayBuffer":op=="replay-save"?"SaveReplayBuffer":null;if(request==null)throw new InvalidOperationException(L.T("Unbekannte OBS-Aktion."));var response=Request(request,null,token);if(op=="replay-save"){var path=Request("GetLastReplayBufferReplay",null,token);return AddonResult.Of(AddonResultCode.Succeeded,L.T("Replay gespeichert: ")+IntegrationJson.Text(path,"savedReplayPath"));}string stateRequest=op.StartsWith("record")?"GetRecordStatus":op.StartsWith("stream")?"GetStreamStatus":"GetReplayBufferStatus";bool active=IntegrationJson.Bool(Request(stateRequest,null,token),"outputActive");return AddonResult.State(action.Title+": "+(active?L.T("aktiv"):L.T("beendet"))+(IntegrationJson.Text(response,"outputPath").Length>0?"\n"+IntegrationJson.Text(response,"outputPath"):""),active?"aktiv":"beendet");
        }
    }
}
